-- [TSMod] npc_prohibit (generated by mods/npc_prohibit/make_mod.py): party characters this cut battle spawns as NPCs
-- are greyed out on the deploy screen, only while the cut battle runs (QUEST_INFO_TSMOD_CUT_BENEDICT). Benedict
local tsmod_np_list = {"UNIT_MASTER_CH_P003"}
local tsmod_np_done = false
local tsmod_np_add = AddInitialPosition
function AddInitialPosition(...)
  if not tsmod_np_done then
    tsmod_np_done = true
    local okq, q = pcall(GetCurrentQuestInfoId)
    if okq and q == "QUEST_INFO_TSMOD_CUT_BENEDICT" then
      local ok, err = pcall(AddProhibitedUnits, tsmod_np_list)
      if TSLOG ~= nil then pcall(TSLOG, "npc_prohibit", ok, err, unpack(tsmod_np_list)) end
    end
  end
  return tsmod_np_add(...)
end
